			  "token": { zh: "词元", domain: "人工智能", gloss: "模型处理文本的最小单位，可能是一个词、一个子词或一个字符。" },
			  "vocabulary": { zh: "词表", domain: "人工智能", gloss: "分词器与模型共同使用的全部词元及其编号的集合。" },
			  "byte pair encoding": { zh: "字节对编码", domain: "人工智能", gloss: "反复合并最高频相邻字节对的子词切分算法，能兼顾词表与未登录词。" },
			  "out-of-vocabulary": { zh: "未登录词", domain: "人工智能", gloss: "不在词表中、模型无法直接表示的词或字符。" },
			  "fine-tuning": { zh: "微调", domain: "人工智能", gloss: "在预训练模型基础上用领域数据继续训练，使其适配特定任务。" },
			  "lora": { zh: "低秩适配", domain: "人工智能", gloss: "低秩适配（Low-Rank Adaptation），只训练插入的小型低秩矩阵即可微调大模型。" },
			  "qlora": { zh: "量化低秩适配", domain: "人工智能", gloss: "把基座模型量化到低位宽再做LoRA微调，大幅降低显存需求。" },
			  "peft": { zh: "参数高效微调", domain: "人工智能", gloss: "参数高效微调（Parameter-Efficient Fine-Tuning），只更新极少量参数来适配下游任务。" },
			  "adapter": { zh: "适配器模块", domain: "人工智能", gloss: "插在预训练层之间的小型可训练模块，换任务时只替换它。" },
			  "quantization": { zh: "量化", domain: "人工智能", gloss: "把模型权重或激活从高精度压到低比特，以省显存并加速推理。" },
			  "distillation": { zh: "蒸馏", domain: "人工智能", gloss: "让小模型学习大模型的输出分布，以较小体量逼近其能力。" },
			  "knowledge distillation": { zh: "知识蒸馏", domain: "人工智能", gloss: "用教师模型的软标签指导学生模型训练，迁移其学到的隐含知识。" },
			  "pruning": { zh: "剪枝", domain: "人工智能", gloss: "删掉贡献很小的权重、通道或层，在精度损失可控下压缩模型。" },
			  "sparsity": { zh: "稀疏性", domain: "人工智能", gloss: "参数或激活中大量元素为零，可利用它跳过无用的计算。" },
