			  "top-p sampling": { zh: "核采样", domain: "人工智能", gloss: "只在累计概率达到阈值的最小词元集合中随机抽取下一个词。" },
			  "top-k sampling": { zh: "限定候选采样", domain: "人工智能", gloss: "每一步只从概率最高的K个候选词中随机抽取一个。" },
