			  "vector database": { zh: "向量数据库", domain: "人工智能", gloss: "专门存储与检索高维向量的数据库，支持近似最近邻搜索。" },
			  "approximate nearest neighbor": { zh: "近似最近邻", domain: "人工智能", gloss: "用索引以少量精度损失换取海量向量中的快速检索。" },
			  "hnsw": { zh: "分层可导航小世界", domain: "人工智能", gloss: "分层可导航小世界（Hierarchical Navigable Small World），常用的高维向量近邻索引结构。" },
