			  "pipeline parallelism": { zh: "流水线并行", domain: "人工智能", gloss: "按层把模型分段放在不同卡上，微批次依次流过形成流水。" },
			  "gradient descent": { zh: "梯度下降", domain: "人工智能", gloss: "沿着损失函数下降最快的方向逐步调整参数以求得最小值。" },
			  "stochastic gradient descent": { zh: "随机梯度下降", domain: "人工智能", gloss: "每次只用一小批样本估计梯度来更新参数，速度快但路径有噪声。" },
			  "backpropagation": { zh: "反向传播", domain: "人工智能", gloss: "按链式法则从输出层往回逐层计算梯度，用于更新网络参数。" },
			  "overfitting": { zh: "过拟合", domain: "人工智能", gloss: "模型把训练数据的噪声也记住了，在新数据上表现明显变差。" },
