			  "batch normalization": { zh: "批归一化", domain: "人工智能", gloss: "按小批量统计把每层输入标准化，使训练更快更稳定。" },
			  "layer normalization": { zh: "层归一化", domain: "人工智能", gloss: "在单个样本的特征维度上做归一化，适合变长序列与Transformer。" },
			  "cross-entropy": { zh: "交叉熵", domain: "人工智能", gloss: "衡量预测分布与真实分布差异的损失，分类任务中最常用。" },
			  "perplexity": { zh: "困惑度", domain: "人工智能", gloss: "语言模型对文本感到意外的程度，数值越低表示预测越准。" },
