			  "learning rate": { zh: "学习率", domain: "人工智能", gloss: "每次参数更新的步长，过大易震荡、过小则收敛缓慢。" },
			  "learning rate schedule": { zh: "学习率调度", domain: "人工智能", gloss: "按训练进度动态调整学习率的策略，通常先升后降。" },
			  "warmup": { zh: "预热", domain: "人工智能", gloss: "训练初期把学习率从很小逐步升上去，避免早期训练不稳定。" },
			  "epoch": { zh: "训练轮次", domain: "人工智能", gloss: "把整个训练集完整过一遍称为一个轮次。" },
